import { settleTheme } from "../helpers/theme-preferences";
import "dotenv/config";
import { randomUUID } from "node:crypto";
import { test, expect } from "../helpers/system-control-browser";
import AxeBuilder from "@axe-core/playwright";
import { encode } from "next-auth/jwt";
import { Pool } from "pg";
import { encryptToken } from "@/lib/crypto";

// Run with npm run test:e2e -- tests/browser/history.spec.ts. Fixtures never queue emails.
test.use({ hasTouch: true });
test("History server triggers, responsive actions, search, and interactive Premium tooltips", async ({
  page,
  context,
}) => {
  const databaseUrl = process.env.DATABASE_URL;
  if (
    !databaseUrl ||
    !["localhost", "127.0.0.1"].includes(new URL(databaseUrl).hostname)
  )
    throw new Error("History browser checks require a local database.");
  const pool = new Pool({ connectionString: databaseUrl });
  const userId = randomUUID(),
    contactId = randomUUID(),
    templateId = randomUUID(),
    campaignId = randomUUID();
  const control = await pool.query(
    `SELECT "paidGatingEnabled" FROM "SystemControl" WHERE key='global'`,
  );
  const originalPaidGating = control.rows[0]?.paidGatingEnabled;
  const pageErrors: string[] = [];
  page.on("pageerror", (error) => pageErrors.push(error.message));
  try {
    await pool.query(
      `INSERT INTO "User" (id,email,name,"googleId","gmailAuthorized","encryptedRefreshToken","gmailScopes","gmailSendOnlyConsentAt","usageBackfillVersion","usageCutoverAt","planOverride","planOverrideStartsAt","planOverrideExpiresAt","planOverrideReason") VALUES ($1,$2,'History Test',$1,true,$3,ARRAY['openid','email','profile','https://www.googleapis.com/auth/gmail.send'],NOW(),1,NOW(),'PAID',NOW()-INTERVAL '1 day',NOW()+INTERVAL '1 day','History browser test')`,
      [
        userId,
        `${userId}@example.test`,
        encryptToken("FAKE-HISTORY-TEST-TOKEN", userId),
      ],
    );
    await pool.query(
      `INSERT INTO "Contact" (id,"userId",name,email,"jobRole") VALUES ($1,$2,'Alex Morgan','[REDACTED_EMAIL]','Software Engineer')`,
      [contactId, userId],
    );
    await pool.query(
      `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Introduction','Hello','Fixture')`,
      [templateId, userId],
    );
    await pool.query(
      `INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,'COMPLETED_WITH_ERRORS')`,
      [campaignId, userId, templateId],
    );
    for (const [name, status, deliveryState] of [
      ["Alex Morgan", "SENT", "DONE"],
      ["Review Person", "FAILED", "UNCERTAIN"],
    ]) {
      await pool.query(
        `INSERT INTO "Send" (id,"campaignId","contactId","recipientName","recipientEmail","recipientRole","recipientCompany","templateName",status,"deliveryState","sentAt") VALUES ($1,$2,$3,$4,$5,'Software Engineer','Example Company','Introduction',$6,$7,$8)`,
        [
          randomUUID(),
          campaignId,
          contactId,
          name,
          `${name.split(" ")[0].toLowerCase()}@example.test`,
          status,
          deliveryState,
          status === "SENT" ? new Date() : null,
        ],
      );
    }
    const salt = "authjs.session-token";
    const token = await encode({
      secret: process.env.AUTH_SECRET!,
      salt,
      token: {
        userId,
        sub: userId,
        name: "History Test",
        email: `${userId}@example.test`,
      },
    });
    await context.addCookies([
      {
        name: salt,
        value: token,
        domain: new URL(test.info().project.use.baseURL!).hostname,
        path: "/",
        httpOnly: true,
        sameSite: "Lax",
      },
    ]);
    await page.goto("/history");
    await expect(
      page.getByRole("heading", { name: "History", exact: true }),
    ).toBeVisible();
    const table = page.getByRole("region", { name: "Delivery history table" });
    const review = table.getByText("Needs review", { exact: true });
    // This server-rendered badge previously crashed Tooltip by passing a lazy RSC child.
    await review.focus();
    await expect(page.getByRole("tooltip")).toContainText("Check Gmail Sent.");
    await expect(review).toHaveAttribute("aria-describedby", /.+/);
    await page.keyboard.press("Escape");
    await expect(page.getByRole("tooltip")).toHaveCount(0);
    for (const theme of ["dark", "light"]) {
      await page.evaluate((value) => {
        document.documentElement.dataset.theme = value;
      }, theme);
      await settleTheme(page);
      expect(
        (await new AxeBuilder({ page }).include("main").analyze()).violations,
      ).toEqual([]);
    }
    const search = page.getByRole("searchbox", { name: "Search history" });
    await search.fill("Alex");
    await expect(page).toHaveURL(/q=Alex/);
    await expect(review).toHaveCount(0);
    await search.fill("no-matching-recipient");
    await search.press("Enter");
    await expect(table).toContainText(
      "No messages match. Try a different search or status.",
    );
    await search.fill("");
    await search.press("Enter");
    const row = table.getByRole("row").filter({ hasText: "Alex Morgan" });
    await row
      .getByRole("button", { name: "Mark replied", exact: true })
      .click();
    await expect(
      row.getByRole("button", { name: "Undo reply", exact: true }),
    ).toBeVisible();
    await page.getByRole("button", { name: "Replied", exact: true }).click();
    await expect(page).toHaveURL(/status=REPLIED/);
    await row.getByRole("button", { name: "Undo reply", exact: true }).click();
    await expect(table).toContainText("No messages match.");
    await page.getByRole("button", { name: "All", exact: true }).click();
    for (const width of [390, 859, 860]) {
      await page.setViewportSize({ width, height: 1000 });
      const action = row.getByRole("button", {
        name: "Mark replied",
        exact: true,
      });
      await action.scrollIntoViewIfNeeded();
      const rect = await action.boundingBox();
      expect(rect).not.toBeNull();
      expect(rect!.x).toBeGreaterThanOrEqual(0);
      expect(rect!.x + rect!.width).toBeLessThanOrEqual(width);
      const header = table.getByRole("columnheader", {
        name: "Recipient",
        exact: true,
      });
      if (width < 860) await expect(header).toBeHidden();
      else await expect(header).toBeVisible();
    }
    await page.emulateMedia({ reducedMotion: "reduce" });
    // Clear hover left by the desktop checks before switching to touch input.
    await page.mouse.move(0, 0);
    await page.keyboard.press("Escape");
    const info = page.getByRole("button", { name: "About Sent today" });
    await info.tap();
    await expect(page.getByRole("tooltip")).toHaveCSS("animation-name", "none");
    const tip = await page.getByRole("tooltip").boundingBox();
    expect(tip!.x).toBeGreaterThanOrEqual(10);
    expect(tip!.x + tip!.width).toBeLessThanOrEqual(850);
    await page.keyboard.press("Escape");
    // Always exercise locked actions, regardless of the local gating default.
    await pool.query(
      `UPDATE "SystemControl" SET "paidGatingEnabled"=true WHERE key='global'`,
    );
    await pool.query(`UPDATE "User" SET "planOverride"='FREE' WHERE id=$1`, [
      userId,
    ]);
    // Resolve the review fixture so it no longer blocks this contact's shortlist.
    await pool.query(
      `UPDATE "Send" SET "deliveryState"='DONE' WHERE "campaignId"=$1 AND status='FAILED'`,
      [campaignId],
    );
    await page.reload();
    const premium = page.getByRole("button", {
      name: "Premium actions",
      exact: true,
    });
    await expect(premium).toBeVisible();
    await premium.focus();
    await expect(page.getByRole("tooltip")).toContainText("Premium required");
    await page.keyboard.press("Tab");
    await expect(
      page.getByRole("link", { name: "View Premium plan", exact: true }),
    ).toBeFocused();
    await page.keyboard.press("Escape");
    await expect(premium).toBeFocused();
    await expect(page.getByRole("tooltip")).toHaveCount(0);

    for (const replied of [false, true]) {
      if (replied) {
        await pool.query(
          `UPDATE "Send" SET status='REPLIED' WHERE "campaignId"=$1 AND status='SENT'`,
          [campaignId],
        );
        await page.reload();
      }
      for (const appearance of ["purple", "vercel"]) {
        for (const theme of ["light", "dark"]) {
          await page.evaluate(
            ({ appearance, theme }) => {
              document.documentElement.dataset.appearance = appearance;
              document.documentElement.dataset.theme = theme;
            },
            { appearance, theme },
          );
          for (const width of [390, 1280]) {
            await page.setViewportSize({ width, height: 1000 });
            for (const [label, explanation] of [
              [
                replied ? "Undo reply" : "Mark replied",
                replied ? "Replied. Click to undo" : "Mark replied",
              ],
              [
                "Add to shortlist",
                "Add from History with Premium. On Free, enter and save this person’s details in Contacts to email them again.",
              ],
            ]) {
              const action = row.getByRole("button", {
                name: label,
                exact: true,
              });
              await expect(action).toBeEnabled();
              await action.scrollIntoViewIfNeeded();
              await page.mouse.move(0, 0);
              // Move focus away after Escape so focusing the trigger opens it again.
              await premium.focus();
              await page.keyboard.press("Escape");
              await action.focus();
              const tooltip = page.getByRole("tooltip");
              await expect(tooltip).toHaveCount(1);
              await expect(
                tooltip.getByText(explanation, { exact: true }),
              ).toBeVisible();
              await expect(
                tooltip.getByText("Premium required", { exact: true }),
              ).toBeVisible();
              const upgrade = tooltip.getByRole("link", {
                name: "View Premium plan",
                exact: true,
              });
              await expect(upgrade).toBeVisible();
              await expect(upgrade).toHaveAttribute("href", "/usage");
              const bounds = await tooltip.boundingBox();
              expect(bounds!.x).toBeGreaterThanOrEqual(10);
              expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(width - 10);
              expect(bounds!.y).toBeGreaterThanOrEqual(10);
              expect(bounds!.y + bounds!.height).toBeLessThanOrEqual(990);
              if (
                !replied &&
                width === (test.info().project.name === "mobile" ? 390 : 1280)
              ) {
                await page.screenshot({
                  path: test
                    .info()
                    .outputPath(
                      `${appearance}-${theme}-${label.replaceAll(" ", "-")}.png`,
                    ),
                });
              }
              await action.focus();
              await page.keyboard.press("Tab");
              await expect(upgrade).toBeFocused();
              await page.keyboard.press("Escape");
              await expect(action).toBeFocused();
              await expect(tooltip).toHaveCount(0);
              await action.click();
              const popup = page.getByRole("dialog", {
                name: "Upgrade to Premium",
                exact: true,
              });
              await expect(popup).toBeVisible();
              await page.keyboard.press("Escape");
              await expect(action).toBeFocused();
              await page.keyboard.press("Escape");
              // A fresh keyboard focus also opens the same combined box.
              await premium.focus();
              await action.focus();
              await expect(tooltip).toContainText(explanation);
              await page.keyboard.press("Escape");
            }
          }
        }
      }
    }
    // Existing shortlist restrictions retain their explanation inside the box.
    for (const explanation of [
      "In shortlist",
      "Contact unavailable",
      "Pending delivery",
    ]) {
      if (explanation === "In shortlist") {
        await pool.query(
          `UPDATE "Contact" SET "followUpRequestedAt"=NOW() WHERE id=$1 AND "userId"=$2`,
          [contactId, userId],
        );
      } else if (explanation === "Contact unavailable") {
        await pool.query(
          `UPDATE "Contact" SET "archivedAt"=NOW() WHERE id=$1 AND "userId"=$2`,
          [contactId, userId],
        );
      } else {
        await pool.query(
          `UPDATE "Send" SET "deliveryState"='UNCERTAIN' WHERE "campaignId"=$1 AND status='FAILED'`,
          [campaignId],
        );
      }
      await page.reload();
      const action = row.getByRole("button", {
        name: "In shortlist",
        exact: true,
      });
      await expect(action).toBeDisabled();
      await action.focus();
      const tooltip = page.getByRole("tooltip");
      await expect(tooltip).toContainText(explanation);
      await expect(tooltip).toContainText("Premium required");
      await expect(
        tooltip.getByRole("link", { name: "View Premium plan" }),
      ).toHaveAttribute("href", "/usage");
      await page.keyboard.press("Escape");
    }
    // The upgrade link still performs its normal navigation.
    await row.getByRole("button", { name: "Undo reply", exact: true }).focus();
    await page
      .getByRole("tooltip")
      .getByRole("link", { name: "View Premium plan" })
      .click();
    await expect(page).toHaveURL(/\/usage$/);
    expect(pageErrors).toEqual([]);
  } finally {
    if (originalPaidGating !== undefined) {
      await pool.query(
        `UPDATE "SystemControl" SET "paidGatingEnabled"=$1 WHERE key='global'`,
        [originalPaidGating],
      );
    }
    await pool.query('DELETE FROM "Campaign" WHERE "userId"=$1', [userId]);
    await pool.query('DELETE FROM "User" WHERE id=$1', [userId]);
    await pool.end();
  }
});
